# ---------------------------------------------------------------------------
# claims: the only thing a mutation is allowed to touch
# ---------------------------------------------------------------------------
def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "holonomy_product_trivial": True,
        "flat_limit_in_closure": False,
        "congruence_census": CONGRUENCE_CENSUS,
        "reweight_live_cases": REWEIGHT_LIVE_CASES,
        "live_sector_links": LIVE_SECTOR_LINKS,
        "generic_square_support": GENERIC_SQUARE_SUPPORT,
        "survivor_distribution": SURVIVOR_DISTRIBUTION,
        "probe_survives_links": PROBE_SURVIVES_LINKS,
        "flat_zero_cells": EXCHANGING_CELLS,
        "exchanging_moduli_cells": EXCHANGING_CELLS,
        "flat_rise_links": FLAT_RISE_LINKS,
        "counterpoint_census": COUNTERPOINT_CENSUS,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "break_topology_identity":
        # the closed-cover holonomy product asserted NOT to be identically 1,
        # which would make the one-plaquette fixture possible after all
        claims["holonomy_product_trivial"] = False
    elif mutation == "claim_flat_limit_in_closure":
        # the hollowness denied: the (4,4,0) witness asserted reachable
        claims["flat_limit_in_closure"] = True
    elif mutation == "break_congruence_census":
        claims["congruence_census"] = {(4, 0, 4): 255, (3, 0, 5): 1}
    elif mutation == "claim_reweighting_reaches_live":
        # THE SUPPORT-PATTERN THEOREM, asserted the other way: some entrywise
        # reweighting is claimed to reach the live sector
        claims["reweight_live_cases"] = 1
    elif mutation == "break_live_sector_census":
        claims["live_sector_links"] = 1
    elif mutation == "claim_nilpotency_survives_generic":
        # nilpotency asserted to survive a generic curved field
        claims["generic_square_support"] = 0
    elif mutation == "claim_worst_case_universal":
        # the scout's "14 of 16 broken" asserted as the law on every fixture
        claims["survivor_distribution"] = ((2, 64),)
        claims["probe_survives_links"] = 0
    elif mutation == "claim_artifact_reading":
        # the REFUTED reading restored: only the two theta rows vanish flat,
        # so the gap would be a reflection-PLANE artifact
        claims["flat_zero_cells"] = 4
    elif mutation == "break_exchange_law":
        claims["exchanging_moduli_cells"] = EXCHANGING_CELLS - 1
    elif mutation == "claim_curvature_settled":
        # P3 asserted REFUTED: no rise anywhere, which is the scout's verdict
        claims["flat_rise_links"] = 0
    elif mutation == "break_flux_census":
        claims["counterpoint_census"] = {(4, 4, 0): 296, (3, 4, 1): 25}
    elif mutation == "drop_open_routes":
        # the two pool-2 leads dropped from the note's required scope
        claims["required_scope_keys"] = tuple(
            key
            for key in SCOPE_KEYS
            if key
            not in (
                "lead_one_support_widening",
                "lead_two_signed_flux",
                "pool_two",
            )
        )
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim"
        )
    return claims


